"""Aligned AM / gate-free coherent / HSV / Cell benchmark.

Byte-order correction (2026-09-23): laboratory ``.rIs`` files are interleaved
big-endian signed int16 I,Q as specified by ``RIS2IQ.m``. Outputs generated by
older revisions of this script with little-endian input are invalid.

Devices:
    iPhone 6s, LG X2 (2019), Galaxy S4 LTE 111.9 MHz.

Milestones:
    P = 1, 32, 100, 200.

All four branches share the same frame timing, content-correlation horizontal
alignment, circular active crop, and raw samples.  The coherent branch keeps
the established smooth row-wise complex phase correction but rejects no
frames.  Coherent HSV encodes the same complex average with hue=phase and
value=log magnitude.

The 3x3 median variants are image-domain presentation/denoising controls.
Metrics are odd/even-frame repeatability, not ground-truth fidelity.  P=1 has
no independent odd/even pair and is therefore reported as N/A.
"""

from __future__ import annotations

import csv
import math
import os
from dataclasses import dataclass
from pathlib import Path
import time

import numpy as np
from PIL import Image, ImageDraw, ImageFilter, ImageFont


ROOT = Path(__file__).resolve().parent
OUTPUT_ROOT = ROOT / "analysis_outputs" / os.environ.get(
    "BENCHMARK_OUTPUT_NAME", "three_device_gatefree_coherent_median_v1"
)
DEFAULT_MILESTONES = (1, 32, 100, 200)
MAX_FRAMES = int(os.environ.get("BENCHMARK_MAX_FRAMES", "200"))
MILESTONE_TEXT = os.environ.get("BENCHMARK_MILESTONES", "").strip()
if MILESTONE_TEXT:
    MILESTONES = tuple(
        sorted(
            {
                int(value.strip())
                for value in MILESTONE_TEXT.split(",")
                if value.strip() and 1 <= int(value.strip()) <= MAX_FRAMES
            }
        )
    )
else:
    MILESTONES = tuple(value for value in DEFAULT_MILESTONES if value <= MAX_FRAMES)
if MAX_FRAMES not in MILESTONES:
    MILESTONES = tuple(sorted((*MILESTONES, MAX_FRAMES)))
SAVE_CHECKPOINT_IMAGES = (
    os.environ.get("BENCHMARK_SAVE_CHECKPOINT_IMAGES", "1").strip() != "0"
)
SAVE_LEGACY_GRAPHS = (
    os.environ.get("BENCHMARK_SAVE_LEGACY_GRAPHS", "1").strip() != "0"
)
FAST_SSIM = os.environ.get("BENCHMARK_FAST_SSIM", "0").strip() == "1"
MAX_ALIGNMENT_SHIFT = 32
SAMPLE_CHUNK = 1 << 20

METHODS = ("AM", "Coherent", "Coherent_HSV", "Cell")
MEDIAN_STATES = ("median_off", "median_3x3")
COLORS = {
    "AM": (24, 93, 169),
    "Coherent": (215, 48, 39),
    "Coherent_HSV": (116, 67, 153),
    "Cell": (35, 139, 69),
}


@dataclass(frozen=True)
class Device:
    key: str
    title: str
    file: Path
    fs: float
    f_h: float
    rows: int
    cols: int
    frame_period: float
    origin_columns: float
    active_rows: np.ndarray
    active_cols: np.ndarray


def circular_indices(one_based_segments: list[tuple[int, int]]) -> np.ndarray:
    parts = [np.arange(first - 1, last, dtype=np.int64) for first, last in one_based_segments]
    return np.concatenate(parts)


