            key="galaxy_s4_lte_111p9M",
            title="Galaxy S4 LTE (111.9 MHz)",
            file=data_root / "111.9mhz_20m_110.89105m_galaxyS4lte_rightmiddle.rIs",
            fs=110.891050e6,
