def read_iq_range(
    handle,
    first_sample: int,
    number_samples: int,
) -> np.ndarray:
    handle.seek(first_sample * 4)
    raw = np.fromfile(handle, dtype=">i2", count=2 * number_samples)
    if raw.size != 2 * number_samples:
        raise RuntimeError(
            f"Short IQ read at {first_sample}: "
            f"wanted {number_samples}, got {raw.size // 2}"
        )
    pairs = raw.reshape(-1, 2)
    iq = pairs[:, 0].astype(np.float32) + 1j * pairs[:, 1].astype(np.float32)
    return iq


def sample_raster(
    iq: np.ndarray,
    first_read: int,
    frame_start: float,
    rows: int,
    cols: int,
    samples_per_line: float,
) -> np.ndarray:
    total = rows * cols
    output = np.empty(total, dtype=np.complex64)
    cell_width = samples_per_line / cols
    for first in range(0, total, SAMPLE_CHUNK):
        last = min(total, first + SAMPLE_CHUNK)
        linear = np.arange(first, last, dtype=np.int64)
        row = linear // cols
        col = linear - row * cols
        position = (
            frame_start
            + row.astype(np.float64) * samples_per_line
            + col.astype(np.float64) * cell_width
            - first_read
        )
        lower = np.floor(position).astype(np.int64)
        alpha = (position - lower).astype(np.float32)
        output[first:last] = (
            (1.0 - alpha) * iq[lower] + alpha * iq[lower + 1]
        )
    return output.reshape(rows, cols)


def column_profile(amplitude: np.ndarray) -> np.ndarray:
    profile = np.mean(amplitude, axis=0, dtype=np.float64)
    profile -= np.mean(profile)
    # Mild circular smoothing suppresses pixel noise without erasing broad
    # blanking/receiver bands used for alignment.
    padded = np.concatenate([profile[-2:], profile, profile[:2]])
    profile = np.convolve(padded, np.ones(5) / 5.0, mode="valid")
    norm = np.linalg.norm(profile)
    return profile / max(norm, np.finfo(float).eps)


def estimate_applied_column_shift(
    profile: np.ndarray,
    reference: np.ndarray,
    maximum_shift: int,
) -> tuple[float, float]:
    shifts = np.arange(-maximum_shift, maximum_shift + 1)
    scores = np.asarray(
        [float(np.dot(np.roll(profile, int(shift)), reference)) for shift in shifts]
    )
    peak = int(np.argmax(scores))
    delta = 0.0
    if 0 < peak < scores.size - 1:
        y1, y2, y3 = scores[peak - 1 : peak + 2]
        denominator = y1 - 2.0 * y2 + y3
        if abs(denominator) > 1e-12:
            delta = float(np.clip(0.5 * (y1 - y3) / denominator, -0.5, 0.5))
    return float(shifts[peak] + delta), float(scores[peak])


def accumulate_cell(
    iq: np.ndarray,
    first_read: int,
    frame_start: float,
    rows: int,
    cols: int,
    samples_per_line: float,
) -> tuple[np.ndarray, np.ndarray]:
    first_sample = math.ceil(frame_start)
    last_sample = math.floor(frame_start + rows * samples_per_line - 1e-9)
    global_sample = np.arange(first_sample, last_sample + 1, dtype=np.int64)
    source = global_sample - first_read
    local = global_sample.astype(np.float64) - frame_start
    row = np.floor(local / samples_per_line).astype(np.int64)
    within = local - row.astype(np.float64) * samples_per_line
    col = np.floor(within / samples_per_line * cols).astype(np.int64)
    valid = (
        (source >= 0)
        & (source < iq.size)
        & (row >= 0)
        & (row < rows)
        & (col >= 0)
        & (col < cols)
    )
    index = row[valid] * cols + col[valid]
    amplitude = np.abs(iq[source[valid]]).astype(np.float64)
    size = rows * cols
    partial_sum = np.bincount(index, weights=amplitude, minlength=size).astype(
        np.float32
    )
    partial_count = np.bincount(index, minlength=size).astype(np.uint32)
    return partial_sum.reshape(rows, cols), partial_count.reshape(rows, cols)


def crop(image: np.ndarray, device: Device) -> np.ndarray:
    return image[np.ix_(device.active_rows, device.active_cols)]


def safe_average(total: np.ndarray, count) -> np.ndarray:
    if np.isscalar(count):
        return total / max(int(count), 1)
    return total / np.maximum(count, 1)


def robust_log(image: np.ndarray) -> np.ndarray:
    values = np.asarray(image, dtype=np.float64)
    positive = values[np.isfinite(values) & (values > 0)]
    if positive.size == 0:
        return np.zeros(values.shape, dtype=np.float64)
    floor_value = np.percentile(positive, 0.1)
    transformed = np.log(np.maximum(values, floor_value))
    center = np.median(transformed)
    scale = 1.4826 * np.median(np.abs(transformed - center))
    transformed = (transformed - center) / max(scale, np.finfo(float).eps)
    transformed[~np.isfinite(transformed)] = 0
    return transformed


def robust_scale(image: np.ndarray) -> np.ndarray:
    transformed = robust_log(image)
    low, high = np.percentile(transformed, [1, 99])
    return np.clip(
        (transformed - low) / max(high - low, np.finfo(float).eps),
        0,
        1,
    ).astype(np.float32)


def shared_robust_scale(
    first: np.ndarray,
    second: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    a = robust_log(first)
    b = robust_log(second)
    combined = 0.5 * (a + b)
    low, high = np.percentile(combined, [1, 99])
    span = max(high - low, np.finfo(float).eps)
    return (
        np.clip((a - low) / span, 0, 1).astype(np.float32),
        np.clip((b - low) / span, 0, 1).astype(np.float32),
    )


def hsv_rgb(complex_image: np.ndarray, value: np.ndarray) -> np.ndarray:
    hue = np.mod((np.angle(complex_image) + np.pi) / (2 * np.pi), 1.0)
    hsv = np.stack(
        [
            np.round(255 * hue).astype(np.uint8),
            np.full(hue.shape, 255, dtype=np.uint8),
            np.round(255 * np.clip(value, 0, 1)).astype(np.uint8),
        ],
        axis=2,
    )
    return np.asarray(Image.fromarray(hsv, "HSV").convert("RGB"), dtype=np.float32) / 255.0


def shared_hsv_rgb(
    first: np.ndarray,
    second: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    first_value, second_value = shared_robust_scale(np.abs(first), np.abs(second))
    return hsv_rgb(first, first_value), hsv_rgb(second, second_value)


def median3(image: np.ndarray) -> np.ndarray:
    values = np.clip(image, 0, 1)
    if values.ndim == 2:
        pil = Image.fromarray(np.round(255 * values).astype(np.uint8), "L")
    else:
        pil = Image.fromarray(np.round(255 * values).astype(np.uint8), "RGB")
    filtered = pil.filter(ImageFilter.MedianFilter(size=3))
    return np.asarray(filtered, dtype=np.float32) / 255.0


def gaussian_blur_float(image: np.ndarray, radius: float = 1.5) -> np.ndarray:
    values = np.asarray(image, dtype=np.float64)
    if FAST_SSIM:
        quantized = np.round(255 * np.clip(values, 0, 1)).astype(np.uint8)
        blurred = Image.fromarray(quantized, "L").filter(
            ImageFilter.GaussianBlur(radius=radius)
        )
        return np.asarray(blurred, dtype=np.float64) / 255.0
    half_width = 5
    coordinate = np.arange(-half_width, half_width + 1, dtype=np.float64)
    kernel = np.exp(-0.5 * (coordinate / radius) ** 2)
    kernel /= kernel.sum()
    horizontal_pad = np.pad(
        values, ((0, 0), (half_width, half_width)), mode="reflect"
    )
    horizontal = np.zeros_like(values)
    for index, weight in enumerate(kernel):
        horizontal += weight * horizontal_pad[:, index : index + values.shape[1]]
    vertical_pad = np.pad(
        horizontal, ((half_width, half_width), (0, 0)), mode="reflect"
    )
    output = np.zeros_like(values)
    for index, weight in enumerate(kernel):
        output += weight * vertical_pad[index : index + values.shape[0], :]
    return output


def ssim_channel(first: np.ndarray, second: np.ndarray) -> float:
    x = np.asarray(first, dtype=np.float32)
    y = np.asarray(second, dtype=np.float32)
    mu_x = gaussian_blur_float(x)
    mu_y = gaussian_blur_float(y)
    sigma_x = gaussian_blur_float(x * x) - mu_x * mu_x
    sigma_y = gaussian_blur_float(y * y) - mu_y * mu_y
    sigma_xy = gaussian_blur_float(x * y) - mu_x * mu_y
    # Quantized/C-accelerated blur can make very small local variances
    # slightly negative. Enforce the covariance-matrix constraints before
    # evaluating SSIM so the result remains physically valid.
    sigma_x = np.maximum(sigma_x, 0.0)
    sigma_y = np.maximum(sigma_y, 0.0)
    covariance_bound = np.sqrt(sigma_x * sigma_y)
    sigma_xy = np.clip(sigma_xy, -covariance_bound, covariance_bound)
    c1 = 0.01**2
    c2 = 0.03**2
    numerator = (2 * mu_x * mu_y + c1) * (2 * sigma_xy + c2)
    denominator = (mu_x * mu_x + mu_y * mu_y + c1) * (
        sigma_x + sigma_y + c2
    )
    ssim_map = numerator / np.maximum(denominator, np.finfo(float).eps)
    return float(np.mean(np.clip(ssim_map, -1.0, 1.0)))


def pair_metrics_scaled(
    first: np.ndarray,
    second: np.ndarray,
) -> tuple[float, float, float]:
    if first.ndim == 2:
        ssim_value = ssim_channel(first, second)
    else:
        ssim_value = float(
            np.mean(
                [
                    ssim_channel(first[:, :, channel], second[:, :, channel])
                    for channel in range(first.shape[2])
                ]
            )
        )
    difference = first.astype(np.float64) - second.astype(np.float64)
    mse = float(np.mean(difference * difference))
    psnr = 10.0 * math.log10(1.0 / max(mse, np.finfo(float).eps))
    half_sum = 0.5 * (first.astype(np.float64) + second.astype(np.float64))
    half_difference = 0.5 * difference
    noise_variance = float(np.var(half_difference))
    signal_variance = float(np.var(half_sum)) - noise_variance
    snr = (
        float("nan")
        if signal_variance <= 0
        else 10.0
        * math.log10(signal_variance / max(noise_variance, np.finfo(float).eps))
    )
    return ssim_value, psnr, snr


def pair_metrics(
    method: str,
    first,
    second,
    use_median: bool,
) -> tuple[float, float, float]:
    if method == "Coherent_HSV":
        a, b = shared_hsv_rgb(first, second)
    else:
        a, b = shared_robust_scale(first, second)
    if use_median:
        a = median3(a)
        b = median3(b)
    return pair_metrics_scaled(a, b)


def display_image(method: str, value, use_median: bool) -> np.ndarray:
    if method == "Coherent_HSV":
        shown = hsv_rgb(value, robust_scale(np.abs(value)))
    else:
        shown = robust_scale(value)
    return median3(shown) if use_median else shown


def save_display(path: Path, image: np.ndarray) -> None:
    if image.ndim == 2:
        pil = Image.fromarray(np.round(255 * image).astype(np.uint8), "L")
    else:
        pil = Image.fromarray(np.round(255 * image).astype(np.uint8), "RGB")
    pil.save(path)


def font(size: int):
    path = Path(r"C:\Windows\Fonts\arial.ttf")
    if path.is_file():
        return ImageFont.truetype(str(path), size=size)
    return ImageFont.load_default()


def make_montage(
    paths: dict[tuple[str, str], Path],
    output: Path,
    title: str,
) -> None:
    panel_width = 360
    panel_height = 600
    title_height = 54
    row_label_width = 120
    canvas = Image.new(
        "RGB",
        (
            row_label_width + panel_width * len(METHODS),
            title_height + panel_height * len(MEDIAN_STATES),
        ),
        "white",
    )
    draw = ImageDraw.Draw(canvas)
    draw.text((12, 12), title, font=font(26), fill="black")
    for column, method in enumerate(METHODS):
        draw.text(
            (row_label_width + column * panel_width + 8, title_height + 8),
            method.replace("_", " "),
            font=font(18),
            fill="black",
        )
    for row, median_state in enumerate(MEDIAN_STATES):
        y_base = title_height + row * panel_height
        draw.text(
            (8, y_base + panel_height // 2 - 12),
            median_state.replace("_", " "),
            font=font(16),
            fill="black",
        )
        for column, method in enumerate(METHODS):
            image = Image.open(paths[(method, median_state)]).convert("RGB")
            image.thumbnail(
                (panel_width - 8, panel_height - 42), Image.Resampling.LANCZOS
            )
            x = (
                row_label_width
                + column * panel_width
                + (panel_width - image.width) // 2
            )
            y = y_base + 38 + (panel_height - 42 - image.height) // 2
            canvas.paste(image, (x, y))
    canvas.save(output)


def draw_metric_graph(
    rows: list[dict],
    device: Device,
    median_state: str,
    metric_field: str,
    ylabel: str,
    output: Path,
) -> None:
    width, height = 1000, 650
    left, right, top, bottom = 110, 50, 65, 90
    canvas = Image.new("RGB", (width, height), "white")
    draw = ImageDraw.Draw(canvas)
    plot_w = width - left - right
    plot_h = height - top - bottom
    selected = [
        row
        for row in rows
        if row["device"] == device.key and row["median"] == median_state
    ]
    finite_values = [
        float(row[metric_field])
        for row in selected
        if math.isfinite(float(row[metric_field]))
    ]
    if not finite_values:
        return
    y_min = min(finite_values)
    y_max = max(finite_values)
    if metric_field == "repeatabilitySSIM":
        y_min = max(-0.05, min(0.0, y_min - 0.05))
        y_max = min(1.0, max(0.2, y_max + 0.05))
    else:
        padding = max(1.0, 0.1 * max(y_max - y_min, 1.0))
        y_min -= padding
        y_max += padding
    if y_max <= y_min:
        y_max = y_min + 1

    def point_x(frames: float) -> float:
        return left + (frames - MILESTONES[0]) / (
            MILESTONES[-1] - MILESTONES[0]
        ) * plot_w

    def point_y(value: float) -> float:
        return top + (y_max - value) / (y_max - y_min) * plot_h

    draw.line((left, top, left, top + plot_h), fill="black", width=2)
    draw.line(
        (left, top + plot_h, left + plot_w, top + plot_h),
        fill="black",
        width=2,
    )
    for tick in range(6):
        value = y_min + tick * (y_max - y_min) / 5
        y = point_y(value)
        draw.line((left, y, left + plot_w, y), fill=(225, 225, 225), width=1)
        draw.text((8, y - 10), f"{value:.3g}", font=font(16), fill="black")
    for frames in MILESTONES:
        x = point_x(frames)
        draw.line(
            (x, top, x, top + plot_h), fill=(235, 235, 235), width=1
        )
        draw.text((x - 14, top + plot_h + 15), str(frames), font=font(17), fill="black")

    for method in METHODS:
        method_rows = sorted(
            [row for row in selected if row["method"] == method],
            key=lambda row: int(row["frames"]),
        )
        points = [
            (point_x(int(row["frames"])), point_y(float(row[metric_field])))
            for row in method_rows
            if math.isfinite(float(row[metric_field]))
        ]
        color = COLORS[method]
        if len(points) >= 2:
            draw.line(points, fill=color, width=4)
        for x, y in points:
            draw.ellipse((x - 6, y - 6, x + 6, y + 6), fill="white", outline=color, width=3)

    draw.text(
        (left, 16),
        f"{device.title}: {ylabel} ({median_state.replace('_', ' ')})",
        font=font(25),
        fill="black",
    )
    draw.text(
        (left + plot_w // 2 - 35, height - 48),
        "Frames",
        font=font(20),
        fill="black",
    )
    draw.text((8, 38), ylabel, font=font(18), fill="black")
    legend_x = left + plot_w - 235
    legend_y = top + 12
    for index, method in enumerate(METHODS):
        y = legend_y + index * 27
        draw.line((legend_x, y + 8, legend_x + 30, y + 8), fill=COLORS[method], width=4)
        draw.text(
            (legend_x + 38, y),
            method.replace("_", " "),
            font=font(16),
            fill="black",
        )
    draw.text(
        (left + 5, top + plot_h - 25),
        "P=1 repeatability: N/A (one frame cannot form odd/even estimates)",
        font=font(14),
        fill=(90, 90, 90),
    )
    canvas.save(output)


def process_device(device: Device) -> list[dict]:
    if not device.file.is_file():
        raise FileNotFoundError(device.file)
    device_dir = OUTPUT_ROOT / device.key
    device_dir.mkdir(parents=True, exist_ok=True)

    rows, cols = device.rows, device.cols
    samples_per_line = device.fs / device.f_h
    cell_width = samples_per_line / cols
    margin_samples = (MAX_ALIGNMENT_SHIFT + 4) * cell_width

    am_all = np.zeros((rows, cols), dtype=np.float32)
    am_odd = np.zeros_like(am_all)
    am_even = np.zeros_like(am_all)
    coh_all = np.zeros((rows, cols), dtype=np.complex64)
    coh_odd = np.zeros_like(coh_all)
    coh_even = np.zeros_like(coh_all)
    cell_sum_all = np.zeros((rows, cols), dtype=np.float32)
    cell_sum_odd = np.zeros_like(cell_sum_all)
    cell_sum_even = np.zeros_like(cell_sum_all)
    cell_count_all = np.zeros((rows, cols), dtype=np.uint32)
    cell_count_odd = np.zeros_like(cell_count_all)
    cell_count_even = np.zeros_like(cell_count_all)
    odd_count = 0
    even_count = 0
    reference_raster = None
    reference_profile = None
    alignment_rows: list[dict] = []
    metric_rows: list[dict] = []
    start_time = time.perf_counter()

    print("\n" + "=" * 72, flush=True)
    print(f"{device.title}: P={MAX_FRAMES}", flush=True)
    print(
        f"raster {rows}x{cols}, fs {device.fs / 1e6:.6f} MS/s, "
        f"fH {device.f_h:.9f} Hz",
        flush=True,
    )
    print("alignment: content-correlation, coherent gate: OFF", flush=True)
    print("=" * 72, flush=True)

    with device.file.open("rb") as handle:
        for frame_index in range(MAX_FRAMES):
            nominal_start = (
                frame_index * device.frame_period
                + device.origin_columns * cell_width
            )
            first_read = max(0, math.floor(nominal_start - margin_samples) - 2)
            last_read = math.ceil(
                nominal_start
                + rows * samples_per_line
                + margin_samples
            ) + 2
            iq = read_iq_range(handle, first_read, last_read - first_read + 1)
            iq -= np.complex64(iq.mean(dtype=np.complex128))

            nominal_raster = sample_raster(
                iq,
                first_read,
                nominal_start,
                rows,
                cols,
                samples_per_line,
            )
            profile = column_profile(np.abs(nominal_raster))
            if reference_profile is None:
                applied_shift = 0.0
                alignment_score = 1.0
            else:
                applied_shift, alignment_score = estimate_applied_column_shift(
                    profile,
                    reference_profile,
                    MAX_ALIGNMENT_SHIFT,
                )
            aligned_start = nominal_start - applied_shift * cell_width
            if abs(applied_shift) < 1e-9:
                raster = nominal_raster
            else:
                raster = sample_raster(
                    iq,
                    first_read,
                    aligned_start,
                    rows,
                    cols,
                    samples_per_line,
                )
            del nominal_raster

            if reference_profile is None:
                reference_profile = column_profile(np.abs(raster))
                reference_raster = raster.copy()

            amplitude = np.abs(raster).astype(np.float32)
            am_all += amplitude
            if frame_index % 2 == 0:
                am_odd += amplitude
                odd_count += 1
            else:
                am_even += amplitude
                even_count += 1

            if frame_index == 0:
                coherent_frame = raster
                line_coherence_median = 1.0
                global_coherence = 1.0
            else:
                line_cross = np.sum(
                    raster * np.conj(reference_raster), axis=1, dtype=np.complex128
                )
                line_denominator = np.sqrt(
                    np.sum(np.abs(raster) ** 2, axis=1, dtype=np.float64)
                    * np.sum(
                        np.abs(reference_raster) ** 2,
                        axis=1,
                        dtype=np.float64,
                    )
                ) + np.finfo(float).eps
                line_coherence = np.abs(line_cross) / line_denominator
                line_coherence_median = float(np.median(line_coherence))
                smooth_cross = np.convolve(
                    line_cross, np.ones(9, dtype=np.float64), mode="same"
                )
                line_phase = np.angle(smooth_cross).astype(np.float32)
                coherent_frame = raster * np.exp(-1j * line_phase[:, None]).astype(
                    np.complex64
                )
                cross = np.vdot(reference_raster.ravel(), coherent_frame.ravel())
                denominator = math.sqrt(
                    float(np.vdot(coherent_frame.ravel(), coherent_frame.ravel()).real)
                    * float(np.vdot(reference_raster.ravel(), reference_raster.ravel()).real)
                ) + np.finfo(float).eps
                global_coherence = float(abs(cross) / denominator)

            # No coherence gate: every frame enters all coherent accumulators.
            coh_all += coherent_frame
            if frame_index % 2 == 0:
                coh_odd += coherent_frame
            else:
                coh_even += coherent_frame

            partial_sum, partial_count = accumulate_cell(
                iq,
                first_read,
                aligned_start,
                rows,
                cols,
                samples_per_line,
            )
            cell_sum_all += partial_sum
            cell_count_all += partial_count
            if frame_index % 2 == 0:
                cell_sum_odd += partial_sum
                cell_count_odd += partial_count
            else:
                cell_sum_even += partial_sum
                cell_count_even += partial_count

            alignment_rows.append(
                {
                    "frame": frame_index + 1,
                    "nominalStart": nominal_start,
                    "appliedImageShiftColumns": applied_shift,
                    "alignedStart": aligned_start,
                    "alignmentScore": alignment_score,
                    "globalCoherenceAfterRowPhase": global_coherence,
                    "medianLineCoherence": line_coherence_median,
                    "accepted": 1,
                }
            )

            frames = frame_index + 1
            if frames in MILESTONES:
                all_values = {
                    "AM": crop(am_all / frames, device).astype(np.float32),
                    "Coherent": crop(np.abs(coh_all / frames), device).astype(
                        np.float32
                    ),
                    "Coherent_HSV": crop(coh_all / frames, device).astype(
                        np.complex64
                    ),
                    "Cell": crop(
                        safe_average(cell_sum_all, cell_count_all), device
                    ).astype(np.float32),
                }
                odd_values = {
                    "AM": crop(safe_average(am_odd, odd_count), device).astype(
                        np.float32
                    ),
                    "Coherent": crop(
                        np.abs(safe_average(coh_odd, odd_count)), device
                    ).astype(np.float32),
                    "Coherent_HSV": crop(
                        safe_average(coh_odd, odd_count), device
                    ).astype(np.complex64),
                    "Cell": crop(
                        safe_average(cell_sum_odd, cell_count_odd), device
                    ).astype(np.float32),
                }
                even_values = None
                if even_count > 0:
                    even_values = {
                        "AM": crop(
                            safe_average(am_even, even_count), device
                        ).astype(np.float32),
                        "Coherent": crop(
                            np.abs(safe_average(coh_even, even_count)), device
                        ).astype(np.float32),
                        "Coherent_HSV": crop(
                            safe_average(coh_even, even_count), device
                        ).astype(np.complex64),
                        "Cell": crop(
                            safe_average(cell_sum_even, cell_count_even), device
                        ).astype(np.float32),
                    }
                saved_paths: dict[tuple[str, str], Path] = {}
                for method in METHODS:
                    for median_state in MEDIAN_STATES:
                        use_median = median_state == "median_3x3"
                        if SAVE_CHECKPOINT_IMAGES:
                            shown = display_image(
                                method, all_values[method], use_median
                            )
                            path = (
                                device_dir
                                / f"{device.key}_P{frames:03d}_{method}_{median_state}.png"
                            )
                            save_display(path, shown)
                            saved_paths[(method, median_state)] = path

                        if even_values is None:
                            ssim_value = float("nan")
                            psnr_value = float("nan")
                            snr_value = float("nan")
                        else:
                            ssim_value, psnr_value, snr_value = pair_metrics(
                                method,
                                odd_values[method],
                                even_values[method],
                                use_median,
                            )
                        metric_rows.append(
                            {
                                "device": device.key,
                                "deviceTitle": device.title,
                                "frames": frames,
                                "method": method,
                                "median": median_state,
                                "repeatabilitySSIM": ssim_value,
                                "repeatabilityPSNR_dB": psnr_value,
                                "repeatabilitySNR_dB": snr_value,
                                "meanGlobalCoherence": float(
                                    np.mean(
                                        [
                                            row["globalCoherenceAfterRowPhase"]
                                            for row in alignment_rows
                                        ]
                                    )
                                ),
                                "acceptedFrames": frames,
                            }
                        )
                if SAVE_CHECKPOINT_IMAGES:
                    make_montage(
                        saved_paths,
                        device_dir / f"{device.key}_P{frames:03d}_all_methods_median.png",
                        f"{device.title}, P={frames}, aligned, gate-free coherent",
                    )
                print(
                    f"checkpoint P={frames}: shift {applied_shift:+.3f} col, "
                    f"coherence {global_coherence:.4f}",
                    flush=True,
                )

            if frames % 20 == 0:
                print(
                    f"processed {frames}/{MAX_FRAMES}, "
                    f"shift {applied_shift:+.3f}, "
                    f"coh {global_coherence:.4f}",
                    flush=True,
                )
            del raster, amplitude, coherent_frame, partial_sum, partial_count, iq

    with (device_dir / f"{device.key}_alignment_diagnostics.csv").open(
        "w", newline="", encoding="utf-8"
    ) as handle:
        writer = csv.DictWriter(handle, fieldnames=alignment_rows[0].keys())
        writer.writeheader()
        writer.writerows(alignment_rows)
    with (device_dir / f"{device.key}_metrics.csv").open(
        "w", newline="", encoding="utf-8"
    ) as handle:
        writer = csv.DictWriter(handle, fieldnames=metric_rows[0].keys())
        writer.writeheader()
        writer.writerows(metric_rows)

    if SAVE_LEGACY_GRAPHS:
        for median_state in MEDIAN_STATES:
            for field, ylabel, stem in (
                ("repeatabilitySSIM", "Repeatability SSIM", "ssim"),
                ("repeatabilitySNR_dB", "Repeatability SNR (dB)", "snr"),
                ("repeatabilityPSNR_dB", "Repeatability PSNR (dB)", "psnr"),
            ):
                draw_metric_graph(
                    metric_rows,
                    device,
                    median_state,
                    field,
                    ylabel,
                    device_dir / f"{device.key}_{stem}_{median_state}.png",
                )

    print(
        f"{device.title} complete in {time.perf_counter() - start_time:.1f} s",
        flush=True,
    )
    return metric_rows


def combine_graphs(devices: list[Device]) -> None:
    for median_state in MEDIAN_STATES:
        for stem in ("ssim", "snr", "psnr"):
            paths = [
                OUTPUT_ROOT
                / device.key
                / f"{device.key}_{stem}_{median_state}.png"
                for device in devices
            ]
            images = [Image.open(path).convert("RGB") for path in paths if path.is_file()]
            if not images:
                continue
            combined = Image.new(
                "RGB",
                (max(image.width for image in images), sum(image.height for image in images)),
                "white",
            )
            y = 0
            for image in images:
                combined.paste(image, (0, y))
                y += image.height
            combined.save(
                OUTPUT_ROOT / f"all_devices_{stem}_{median_state}.png"
            )


def main() -> None:
    OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    devices = make_devices()
    all_rows: list[dict] = []
    for device in devices:
        all_rows.extend(process_device(device))
    if all_rows:
        with (OUTPUT_ROOT / "three_device_gatefree_median_metrics.csv").open(
            "w", newline="", encoding="utf-8"
        ) as handle:
            writer = csv.DictWriter(handle, fieldnames=all_rows[0].keys())
            writer.writeheader()
            writer.writerows(all_rows)
    if SAVE_LEGACY_GRAPHS:
        combine_graphs(devices)
    print(f"\nAll outputs: {OUTPUT_ROOT}", flush=True)


if __name__ == "__main__":
    main()
